// Extrai as hashtags da resposta do Gemini e monta o objeto final.
// Inclui fallback: se a IA falhar por qualquer motivo, usa hashtags genéricas
// para não interromper o fluxo (a postagem ainda será salva e notificada).

const aiResponse = $input.first().json;
const taskData = $('Extrair Dados da Tarefa').first().json;

let hashtags = '';
try {
  hashtags = aiResponse.candidates[0].content.parts[0].text.trim();
} catch (e) {
  hashtags = '#marketing #instagram #saude #profissional #conteudo #branding #autoridade #medico #dentista #advogado';
  console.log('FALLBACK ativado — hashtags padrão. Erro original:', e.message);
}

// Normaliza: garante que todas as tags começam com #
hashtags = hashtags
  .split(/\s+/)
  .filter(t => t.length > 1)
  .map(t => t.startsWith('#') ? t : '#' + t)
  .join(' ');

const tokensUsed = aiResponse.usageMetadata?.candidatesTokenCount || 0;

return [{
  json: {
    ...taskData,
    hashtags,
    ia_model: 'gemini-2.5-flash-lite',
    full_caption: taskData.legenda + '\n\n' + hashtags,
    ia_tokens_used: tokensUsed
  }
}];

